use super::*;
use serde_json::json;

fn base() -> Value {
    let mut g = json!({ "implementations": [] });
    set_impl(&mut g, json!({
        "id": "t.ts", "tech": "typescript", "role": "algorithm", "name": "t",
        "composes": ["typescript.number"], "code": "// real",
        "src": "features/x/t.ts", "folder": "features/x",
        "tests": [{ "name": "t suite", "src": "…" }], "vizCode": "({})"
    })).unwrap();
    g
}
fn rec(g: &Value) -> Value {
    implementations_of(g).into_iter().find(|i| i["id"] == "t.ts").unwrap().clone()
}

#[test]
fn a_partial_write_preserves_every_field_it_did_not_supply() {
    // #4154 / requests #49 + #50: this used to be `*existing = im`, so a domain-only edit deleted
    // `folder`, `src`, `tests` and `vizCode` outright. `tests` has no flag AT ALL, so every write
    // dropped it — which stalled a reorg across 16 entries carrying real vitest suites.
    let mut g = base();
    set_impl(&mut g, json!({ "id": "t.ts", "tech": "typescript", "role": "algorithm", "name": "t", "domain": "d" })).unwrap();
    let r = rec(&g);
    assert_eq!(r["domain"], "d", "the supplied field is written");
    assert_eq!(r["src"], "features/x/t.ts", "provenance survives");
    assert_eq!(r["folder"], "features/x");
    assert_eq!(r["tests"][0]["name"], "t suite", "the unflagged field survives");
    assert_eq!(r["vizCode"], "({})");
    assert_eq!(r["composes"][0], "typescript.number", "an omitted composes is not blanked");
    assert_eq!(r["code"], "// real");
}

#[test]
fn a_supplied_field_still_overwrites() {
    // Merging must not make a write inert — the whole point is that it changes what you asked for.
    let mut g = base();
    set_impl(&mut g, json!({ "id": "t.ts", "tech": "typescript", "role": "algorithm", "name": "t2", "code": "// new" })).unwrap();
    let r = rec(&g);
    assert_eq!(r["name"], "t2");
    assert_eq!(r["code"], "// new");
}

#[test]
fn a_null_removes_the_field_so_deletion_is_still_possible() {
    // With merge, omission can no longer mean removal — so `--clear` sends a null and this drops it.
    let mut g = base();
    set_impl(&mut g, json!({ "id": "t.ts", "tech": "typescript", "role": "algorithm", "name": "t", "vizCode": null })).unwrap();
    let r = rec(&g);
    assert!(r.get("vizCode").is_none(), "cleared outright, not left as a null");
    assert_eq!(r["src"], "features/x/t.ts", "clearing one field touches no other");
}

#[test]
fn a_new_impl_still_gets_the_required_composes_array() {
    // The CLI now omits `composes` unless supplied, so an INSERT must still land the shape the model
    // expects rather than a record missing a required field.
    let mut g = json!({ "implementations": [] });
    let inserted = set_impl(&mut g, json!({ "id": "n.ts", "tech": "typescript", "role": "algorithm", "name": "n" })).unwrap();
    assert!(!inserted, "a new id inserts");
    let r = implementations_of(&g).into_iter().find(|i| i["id"] == "n.ts").unwrap().clone();
    assert_eq!(r["composes"], json!([]));
}

/// WRITE AN EDGE AND READ IT BACK, in one process.
///
/// This is the test the tier did not have, and its absence is the whole finding of
/// `the-edge-tier-is-empty-integration-tests-were-never-routed-onto-edges`: the verbs shipped,
/// `doctor` learned to report missing/pending/dangling edges, and the store held NOTHING. Every
/// check that existed asked whether the code was correct; none asked whether it had ever run. So
/// "the verbs exist" was read as "the tier has data" for weeks.
///
/// A round trip cannot prove the tier is populated — only a census can — but it does pin the one
/// thing that would make an empty store unexplainable: that a write is readable afterwards.
#[test]
fn an_edge_written_is_an_edge_read_back() {
    let mut g = json!({ "version": 2, "implementations": [] });
    assert!(edges_of(&g).is_empty(), "a fresh graph has no edges");

    let created = set_edge(
        &mut g,
        json!({ "id": "a--b", "members": ["a.ts", "b.ts"], "src": "src/x/ab.test.ts" }),
    )
    .expect("a two-member edge is accepted");
    assert!(!created, "the first write reports NEW (not an update)");

    let back = edges_of(&g);
    assert_eq!(back.len(), 1, "the write is visible to the very next read: {g}");
    assert_eq!(back[0]["members"], json!(["a.ts", "b.ts"]));
    assert_eq!(back[0]["src"], json!("src/x/ab.test.ts"));

    // MERGING, like every other store write (#4154): a later `--src`-only update must not have to
    // resupply the members, and must not silently drop them.
    let updated = set_edge(&mut g, json!({ "id": "a--b", "src": "src/x/moved.test.ts" }))
        .expect("an update needs no members");
    assert!(updated, "the second write reports an UPDATE");
    let back = edges_of(&g);
    assert_eq!(back.len(), 1, "an update is not a second edge");
    assert_eq!(back[0]["members"], json!(["a.ts", "b.ts"]), "unsupplied keys are PRESERVED");
    assert_eq!(back[0]["src"], json!("src/x/moved.test.ts"));

    assert!(remove_edge(&mut g, "a--b"), "and it can be removed by the id it was written under");
    assert!(edges_of(&g).is_empty());
}

/// A one-member edge is a NODE test wearing the wrong shape, and is refused rather than stored —
/// otherwise the isolation the node tier gets from `bsc graph test <id>` is quietly lost.
#[test]
fn an_edge_over_one_record_is_refused() {
    let mut g = json!({ "version": 2, "implementations": [] });
    let err = set_edge(&mut g, json!({ "id": "solo", "members": ["a.ts"] })).unwrap_err();
    assert!(err.contains("two"), "the refusal says what is wrong: {err}");
    assert!(edges_of(&g).is_empty(), "and nothing is stored: {g}");
    // A NEW edge with no members at all is refused for the same reason, rather than stored blank.
    assert!(set_edge(&mut g, json!({ "id": "empty" })).is_err());
    assert!(edges_of(&g).is_empty());
}

// ── THE SEED RECONCILE'S EDGE HALF (`a-rust-record-test-runs-and-an-edge-reaches-the-seed`) ───────
//
// `reconcile_seed` copied implementations and nothing else, so an edge that reached the packaged seed
// was invisible on every machine that already had a runtime store — and that is every developer box
// here. `load()` falls back WHOLLY to the seed only when NO store file exists, which is why the gap
// hid behind a fresh-install check that passed. These drive `reconcile_edges_into` directly: it takes
// the seed's edges as an ARGUMENT precisely so this needs no `set_var("BSC_DATA_DIR", …)`, the
// process-global mutation that passes under nextest and races under `cargo test`.

fn edge(id: &str, src: &str) -> Value {
    json!({ "id": id, "members": ["a.rs", "b.rs"], "src": src })
}

#[test]
fn a_seed_edge_the_store_has_never_seen_is_added() {
    // The exact measured shape: a store that has authored SOMETHING, so `load()` reads it rather than
    // falling back to the seed, and holds no `edges` key at all.
    let mut g = json!({ "implementations": [{ "id": "local.rs" }] });
    assert!(reconcile_edges_into(&mut g, &[edge("seed--e", "src/x.test.ts")]));
    assert_eq!(edges_of(&g).len(), 1);
    assert_eq!(edges_of(&g)[0]["id"], "seed--e");
}

#[test]
fn a_local_edit_to_a_seed_edge_is_never_overwritten() {
    // Same rule as the implementation half. A librarian's edit surviving the next read is the whole
    // reason this appends rather than merges.
    let mut g = json!({ "implementations": [], "edges": [{ "id": "e", "members": ["mine.rs", "too.rs"] }] });
    assert!(!reconcile_edges_into(&mut g, &[edge("e", "src/theirs.test.ts")]));
    assert_eq!(edges_of(&g)[0]["members"][0], "mine.rs");
    assert!(edges_of(&g)[0].get("src").is_none(), "the seed's copy did not overwrite the local one");
}

/// ADDITIVE, exactly as `edges_of` is. Without this every store on every box would grow an
/// `"edges": []` key on its next READ, churning a file nobody edited.
#[test]
fn nothing_missing_does_not_invent_an_edges_key() {
    let mut g = json!({ "implementations": [] });
    assert!(!reconcile_edges_into(&mut g, &[]));
    assert!(g.get("edges").is_none(), "a read invented an `edges` key");
}

/// A tombstone is keyed on an IMPLEMENTATION id, and an edge id is a different namespace. Consulting
/// one list for two namespaces would let an impl's tombstone silently retire an unrelated edge.
#[test]
fn an_implementation_tombstone_does_not_retire_an_edge_of_the_same_name() {
    let mut g = json!({ "implementations": [], "suppressions": [{ "id": "shared-name" }] });
    assert!(reconcile_edges_into(&mut g, &[edge("shared-name", "src/x.test.ts")]));
    assert_eq!(edges_of(&g).len(), 1);
}
